window.MAPS = (window.MAPS||[]).concat([
{ cat:"Grammar: Structures", type:"Grammar", lvl:"C2", icon:"📜", t:"The Subjunctive and Mandative Structures", es:"El subjuntivo y las estructuras mandativas", d:"El subjuntivo formal británico: were, should y la forma base tras verbos de exigencia.",
 boxes:[
  {e:"📋", h:"Negative and passive mandatives", es:"Mandativos negativos y pasivos", i:[["The committee ruled that the motion not be put to a vote.","El comité dictaminó que la moción no se sometiera a votación."],["It is desirable that the post be advertised.","Es deseable que el puesto se anuncie."],["It was agreed that he be reimbursed.","Se acordó que se le reembolsara."]], ex:["The court ordered that the documents be disclosed.","El tribunal ordenó que se divulgaran los documentos."]},
  {e:"🇬🇧", h:"Triggers beyond verbs", es:"Desencadenantes que no son verbos", i:[["It is a requirement that applicants be over 18.","Es un requisito que los solicitantes sean mayores de 18 años."],["Her insistence that the matter be dropped surprised us.","Su insistencia en que se dejara el asunto nos sorprendió."],["It is only right that she be compensated.","Es justo que se la indemnice."]], ex:["It is of the utmost importance that nobody leave early.","Es de suma importancia que nadie se vaya antes."]},
  {e:"🌀", h:"Be-subjunctive in fixed concessions", es:"'Be' subjuntivo en concesiones fijas", i:[["Be he friend or foe, he must be heard.","Sea amigo o enemigo, debe ser escuchado."],["Be it ever so humble, there's no place like home.","Por humilde que sea, como el hogar no hay nada."],["Far be it from me to criticise.","Lejos de mí criticar."],["As it were: a hedge meaning 'so to speak'.","As it were: atenuador que significa 'por así decirlo'."]], ex:["Heaven forbid that it should come to that.","Dios no quiera que se llegue a eso."]},
  {e:"🙏", h:"Fixed subjunctive formulae", es:"Fórmulas fijas", i:[["So be it.","Que así sea."],["Perish the thought!","¡Ni pensarlo!"],["Woe betide anyone who is late.","¡Ay de quien llegue tarde!"]], ex:["Heaven help us all.","Que el cielo nos ayude a todos."]},
  {e:"🔀", h:"Wish, if only, would rather", es:"Wish, if only, would rather", i:[["If only I were braver.","Ojalá fuera más valiente."],["I wish you wouldn't interrupt.","Ojalá no interrumpieras."],["It's high time we left.","Ya es hora de que nos vayamos."]], ex:["I'd rather you didn't mention it.","Preferiría que no lo mencionaras."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ It is essential that he must be informed.","✓ It is essential that he be informed. — tras that se usa la forma base, sin modal."],["✗ I demand that he doesn't be told.","✓ I demand that he not be told. — la negación se forma sin 'do'."],["✗ It's high time we leave.","✓ It's high time we left. — con 'high time' se usa el pasado."]], ex:["It is imperative that every member vote.","Es imperativo que cada miembro vote."]}
 ], qs:[
  {q:"Complete formally: It is crucial that every candidate ____ (submit) the form.", a:"submit — forma base, sin -s."},
  {q:"Complete: ____ it from me to criticise.", a:"Far be — Far be it from me to criticise."},
  {q:"Correct: It's high time we go home.", a:"It's high time we went home."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"C2", icon:"🔃", t:"Inversion for Rhetorical Effect", es:"Inversión para efecto retórico", d:"Inversión tras negativos, 'so', 'such' y fórmulas literarias y oratorias.",
 boxes:[
  {e:"🚫", h:"Negative adverbials", es:"Adverbiales negativos", i:[["Never have I seen such courage.","Nunca he visto tanto valor."],["Rarely does one encounter such candour.","Rara vez se encuentra tanta franqueza."],["Not once did he look back.","Ni una sola vez miró atrás."]], ex:["Seldom has a speech moved me so deeply.","Pocas veces un discurso me ha conmovido tanto."]},
  {e:"⏳", h:"Only and no sooner", es:"Only y no sooner", i:[["Only then did I realise my error.","Solo entonces me di cuenta de mi error."],["No sooner had we sat down than the lights failed.","Apenas nos sentamos, se fue la luz."],["Only by working together can we succeed.","Solo trabajando juntos podemos lograrlo."]], ex:["Hardly had she spoken when the door opened.","Apenas había hablado cuando se abrió la puerta."]},
  {e:"🧱", h:"So and such fronted", es:"So y such al inicio", i:[["So absorbed was he that he missed his stop.","Tan absorto estaba que se pasó su parada."],["Such was the noise that nobody slept.","Tal era el ruido que nadie durmió."],["Such is life.","Así es la vida."]], ex:["So severe was the storm that the ferry was cancelled.","Tan fuerte fue la tormenta que cancelaron el ferri."]},
  {e:"🎭", h:"Literary fronting", es:"Anteposición literaria", i:[["Down the lane came the cart.","Por el camino venía el carro."],["Gone are the days of cheap rent.","Atrás quedaron los días de alquileres baratos."],["Along the shore walked a solitary figure.","Por la orilla caminaba una figura solitaria."]], ex:["Into the room strode the Duchess.","En la sala irrumpió la Duquesa."]},
  {e:"🔗", h:"Neither, nor, as", es:"Neither, nor, as", i:[["Nor did she apologise.","Y tampoco se disculpó."],["Neither was the evidence convincing.","Tampoco la prueba era convincente."],["Tired as he was, he kept going.","Aunque estaba cansado, siguió."]], ex:["Try as they might, they could not open it.","Por más que lo intentaron, no pudieron abrirlo."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ Never I have seen it.","✓ Never have I seen it. — el auxiliar va antes del sujeto."],["✗ Hardly she had left when...","✓ Hardly had she left when... — inversión obligatoria."],["✗ Only then I understood.","✓ Only then did I understand. — se necesita 'did'."]], ex:["Under no circumstances should you open it.","Bajo ninguna circunstancia debes abrirlo."]}
 ], qs:[
  {q:"Invert: I had no sooner arrived than it rained.", a:"No sooner had I arrived than it rained."},
  {q:"Complete: Only after midnight ____ the guests leave.", a:"did — Only after midnight did the guests leave."},
  {q:"Correct: Under no circumstances you should resign.", a:"Under no circumstances should you resign."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"C2", icon:"✂️", t:"Ellipsis and Substitution", es:"Elipsis y sustitución", d:"Cómo omitir o sustituir palabras sin perder claridad, en habla y escritura.",
 boxes:[
  {e:"✂️", h:"Ellipsis after conjunctions", es:"Elipsis tras conjunciones", i:[["While waiting, she read.","Mientras esperaba, leyó."],["If necessary, call me.","Si es necesario, llámame."],["Once opened, the tin must be refrigerated.","Una vez abierta, la lata debe refrigerarse."]], ex:["Though tired, he carried on.","Aunque cansado, siguió."]},
  {e:"🔁", h:"One, the former, the latter, such", es:"One, the former, the latter, such", i:[["I prefer the red one to the blue ones.","Prefiero el rojo a los azules."],["Of the two proposals, the former is cheaper.","De las dos propuestas, la primera es más barata."],["Such is the case with most start-ups.","Ese es el caso de la mayoría de las empresas emergentes."]], ex:["Of the two, the latter is more realistic.","De las dos, la segunda es más realista."]},
  {e:"🧩", h:"Gapping and stripping", es:"Elipsis de verbo repetido", i:[["Tom had the fish and Mary the steak.","Tom pidió pescado y Mary, carne."],["Some were pleased, others not.","Algunos estaban contentos; otros, no."],["I play the piano; my brother, the violin.","Yo toco el piano; mi hermano, el violín."]], ex:["He likes jazz, and she, blues.","A él le gusta el jazz y a ella, el blues."]},
  {e:"🗣️", h:"Spoken ellipsis", es:"Elipsis hablada", i:[["Seen the news?","¿Has visto las noticias?"],["Sounds good.","Suena bien."],["Fancy a cuppa?","¿Quieres un té?"]], ex:["Don't know, to be honest.","No sé, a decir verdad."]},
  {e:"🪄", h:"To-infinitive ellipsis", es:"Infinitivo elíptico", i:[["Come if you'd like to.","Ven si quieres."],["I didn't want to, but I had to.","No quería, pero tuve que hacerlo."],["You may stay, if you wish.","Puedes quedarte, si quieres."]], ex:["I'd love to, but I'm afraid I can't.","Me encantaría, pero me temo que no puedo."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ While waiting, the bus arrived.","✓ While we were waiting, the bus arrived. — el sujeto omitido debe coincidir."],["✗ I'd love to come, but I can't to.","✓ I'd love to come, but I can't. — tras modal no va 'to'."],["✗ the former of the three options","✓ the first of the three options — former y latter solo se usan con dos."]], ex:["Having finished, she left.","Al terminar, se fue."]}
 ], qs:[
  {q:"Of two options, which formal word means 'the second one mentioned'?", a:"the latter"},
  {q:"Complete (ellipsis): Some were pleased, others ____.", a:"not"},
  {q:"Correct: Walking home, the rain began.", a:"Por ejemplo: Walking home, I got caught in the rain. — el sujeto elíptico debe ser quien camina."}
 ] },

{ cat:"Grammar: Structures", type:"Grammar", lvl:"C2", icon:"🏰", t:"Archaic and Literary Verb Forms", es:"Formas verbales arcaicas y literarias", d:"Thou, hath, whence y otras formas que aparecen en la Biblia, Shakespeare y la poesía.",
 boxes:[
  {e:"🕯️", h:"Thou, thee, thy", es:"Pronombres arcaicos", i:[["Thou art wise.","Tú eres sabio."],["I love thee.","Te amo."],["Thy kingdom come.","Venga tu reino."]], ex:["Wherefore art thou Romeo?","¿Por qué eres tú Romeo?"]},
  {e:"✒️", h:"-eth and -est endings", es:"Terminaciones -eth y -est", i:[["He giveth and he taketh away.","Él da y él quita."],["Thou knowest the truth.","Tú conoces la verdad."],["Thou hast spoken well.","Has hablado bien."]], ex:["God loveth a cheerful giver.","Dios ama al que da con alegría."]},
  {e:"🧭", h:"Archaic adverbs", es:"Adverbios arcaicos", i:[["whence = from where; whither = to where","whence = de dónde; whither = a dónde"],["hence, thence, thither","de aquí, de allí, hacia allí"],["Whence comest thou?","¿De dónde vienes?"]], ex:["Go hence and trouble us no more.","Vete de aquí y no nos molestes más."]},
  {e:"⚖️", h:"Shall in solemn use", es:"Shall solemne", i:[["Thou shalt not steal.","No robarás."],["We shall overcome.","Venceremos."],["They shall not pass.","No pasarán."]], ex:["The accused shall remain in custody.","El acusado permanecerá bajo custodia."]},
  {e:"📖", h:"Survivals in modern English", es:"Supervivencias hoy", i:[["albeit = although it be","albeit = aunque"],["nevertheless, notwithstanding, hereby, thereof","no obstante, sin perjuicio de, por la presente, de ello"],["methinks, forsooth (jocular)","methinks, forsooth (en tono jocoso)"]], ex:["A small, albeit significant, victory.","Una pequeña, aunque significativa, victoria."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ Thou are kind.","✓ Thou art kind. — thou va con art."],["✗ My brother giveth me books.","✓ My brother gives me books. — -eth solo es bíblico o poético."],["✗ Use 'thee' as subject.","✓ Thou = sujeto; thee = objeto. — como you/you."]], ex:["Whither goest thou?","¿Adónde vas?"]}
 ], qs:[
  {q:"Which is the subject form: thou or thee?", a:"thou"},
  {q:"What does 'whence' mean?", a:"De dónde (from where)."},
  {q:"Correct: Thou are welcome.", a:"Thou art welcome."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"C2", icon:"🎚️", t:"Subtle Modality: Dare, Need, Ought, Shall", es:"Modalidad sutil: dare, need, ought, shall", d:"Los modales marginales y sus matices en registro formal y británico.",
 boxes:[
  {e:"😨", h:"Dare as modal", es:"Dare como modal", i:[["How dare you!","¡Cómo te atreves!"],["I daren't ask him.","No me atrevo a preguntarle."],["Dare we hope for better news?","¿Nos atrevemos a esperar mejores noticias?"]], ex:["I dare say you're right.","Me atrevería a decir que tienes razón."]},
  {e:"🙅", h:"Need as a modal verb", es:"Need como modal", i:[["Need I say more?","¿Hace falta que diga más?"],["There needn't be any trouble.","No tiene por qué haber problemas."],["I need hardly say how grateful we are.","Apenas hace falta decir lo agradecidos que estamos."]], ex:["You need only ask.","Basta con que preguntes."]},
  {e:"📏", h:"May well, might just, would sooner", es:"May well, might just, would sooner", i:[["You may well be right.","Muy bien puedes tener razón."],["She might just win.","Quizá incluso gane."],["I'd sooner resign than apologise.","Antes renunciaría que disculparme."]], ex:["We had best leave now.","Más nos vale irnos ya."]},
  {e:"🧭", h:"Shall in questions", es:"Shall en preguntas", i:[["Shall I open the window?","¿Abro la ventana?"],["Shall we dance?","¿Bailamos?"],["Let's go, shall we?","Vámonos, ¿te parece?"]], ex:["Shall I take your coat?","¿Le recibo el abrigo?"]},
  {e:"🔮", h:"Would for habit and irritation", es:"Would para hábito e irritación", i:[["Every summer we would go to Cornwall.","Cada verano íbamos a Cornualles."],["He would say that, wouldn't he?","Eso es lo que diría él, ¿no?"],["She would leave her keys everywhere.","Ella, cómo no, dejaba las llaves por todas partes."]], ex:["He would keep interrupting me.","No paraba de interrumpirme."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ You needn't to come.","✓ You needn't come. — needn't no lleva 'to'."],["✗ He daren't to ask.","✓ He daren't ask. — modal sin 'to'."],["✗ You oughtn't to had said that.","✓ You oughtn't to have said that. — ought to + have + participio."]], ex:["You mustn't tell her; you needn't tell her.","No debes decírselo; no hace falta que se lo digas."]}
 ], qs:[
  {q:"Complete with the modal verb: ____ I say more? (formal rhetorical question)", a:"Need"},
  {q:"Complete with a modal, not 'used to': Every winter my grandfather ____ light the fire at five.", a:"would"},
  {q:"Correct: How dare you to speak to me like that!", a:"How dare you speak to me like that!"}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"C2", icon:"🏗️", t:"Complex Noun Phrases and Nominalisation", es:"Sintagmas nominales complejos y nominalización", d:"Condensar ideas en sustantivos, típico de la prosa académica y periodística.",
 boxes:[
  {e:"🧱", h:"Pre- and post-modification", es:"Premodificación y posmodificación", i:[["a long-awaited report on rural poverty","un esperado informe sobre la pobreza rural"],["the man standing by the door","el hombre que está junto a la puerta"],["a deeply flawed, politically motivated inquiry","una investigación muy defectuosa y de motivación política"]], ex:["The recently published study on sleep disorders has been criticised.","El estudio recién publicado sobre trastornos del sueño ha sido criticado."]},
  {e:"🔄", h:"Apposition and noun-phrase chains", es:"Aposición y cadenas nominales", i:[["Mr Ellis, a retired judge, spoke.","El Sr. Ellis, juez jubilado, habló."],["the city of Bath","la ciudad de Bath"],["the fact, so often ignored, that wages lag behind prices","el hecho, tantas veces ignorado, de que los salarios van a la zaga de los precios"]], ex:["Her book, a study of grief, won a prize.","Su libro, un estudio sobre el duelo, ganó un premio."]},
  {e:"📰", h:"Journalese compression", es:"Compresión periodística", i:[["a council-funded housing scheme","un plan de vivienda financiado por el consejo"],["a last-ditch, cross-party effort","un esfuerzo desesperado de todos los partidos"],["a make-or-break moment","un momento decisivo"]], ex:["The government's much-trumpeted reform has stalled.","La tan pregonada reforma del gobierno se ha estancado."]},
  {e:"📚", h:"Abstract noun + that / of", es:"Sustantivo abstracto + that / of", i:[["the fact that prices rose","el hecho de que los precios subieran"],["the likelihood of rain","la probabilidad de lluvia"],["a tendency to exaggerate","una tendencia a exagerar"]], ex:["There is growing evidence that diets affect mood.","Hay cada vez más pruebas de que la dieta afecta al ánimo."]},
  {e:"🧮", h:"Of-genitive and double genitive", es:"Genitivo con of y doble genitivo", i:[["a friend of my brother's","un amigo de mi hermano"],["the roof of the house","el techo de la casa"],["that smile of hers","esa sonrisa suya"]], ex:["It's a habit of his that annoys me.","Es una costumbre suya que me molesta."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ a ten-years-old boy","✓ a ten-year-old boy — el sustantivo en compuesto va en singular."],["✗ the fact of that prices rose","✓ the fact that prices rose — sin 'of'."],["✗ a long awaited-report","✓ a long-awaited report — el guion une el compuesto."]], ex:["a three-hour delay","un retraso de tres horas"]}
 ], qs:[
  {q:"Nominalise: They failed to agree, which caused delay.", a:"Their failure to agree caused delay."},
  {q:"Correct: a five-years plan", a:"a five-year plan"},
  {q:"Complete: a colleague ____ my sister's (double genitive).", a:"of — a colleague of my sister's."}
 ] },

{ cat:"Grammar: Structures", type:"Grammar", lvl:"C2", icon:"🔖", t:"Articles and Determiners: Edge Cases", es:"Artículos y determinantes: casos límite", d:"Cuándo el artículo cambia el significado o se omite en usos institucionales y abstractos.",
 boxes:[
  {e:"🏛️", h:"Institutions without the", es:"Instituciones sin the", i:[["in hospital / in the hospital (as a visitor)","hospitalizado / en el edificio (de visita)"],["at university; at the university","en la universidad (estudiar); en el edificio"],["go to prison / go to the prison","ir a prisión (como preso) / ir a la cárcel (de visita)"]], ex:["She was sent to prison for fraud.","La enviaron a prisión por fraude."]},
  {e:"🌍", h:"Generic reference", es:"Referencia genérica", i:[["The tiger is endangered.","El tigre está en peligro."],["Tigers are endangered.","Los tigres están en peligro."],["The rich get richer.","Los ricos se hacen más ricos."]], ex:["The elderly deserve respect.","Los ancianos merecen respeto."]},
  {e:"🔢", h:"Indefinite a with change in meaning", es:"A con cambio de sentido", i:[["a Mr Brown called (someone I don't know)","llamó un tal Brown"],["a Picasso (a work by him)","un Picasso (obra suya)"],["Time / a time; experience / an experience","tiempo / una vez; experiencia / una vivencia"]], ex:["It was an experience I'll never forget.","Fue una experiencia que nunca olvidaré."]},
  {e:"🧩", h:"Fixed phrases without articles", es:"Frases fijas sin artículo", i:[["by car, on foot, at dawn","en coche, a pie, al amanecer"],["in time vs on time","a tiempo (con margen) vs puntual"],["day by day, hand in hand","día a día, de la mano"]], ex:["We arrived in time for the curtain.","Llegamos a tiempo para el telón."]},
  {e:"📐", h:"Quantifiers: few, a few, little, a little", es:"Cuantificadores", i:[["Few people knew. (almost none)","Pocos sabían. (casi nadie)"],["A few people knew. (some)","Algunos sabían. (unos cuantos)"],["Little hope remains.","Queda poca esperanza."]], ex:["Quite a few guests arrived late.","Bastantes invitados llegaron tarde."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ The life is hard.","✓ Life is hard. — sin the para conceptos generales."],["✗ She's in the hospital as a patient. (BrE)","✓ She's in hospital. — como paciente, sin the en inglés británico."],["✗ I have a little friends.","✓ I have few friends. — friends es contable."]], ex:["Information is power.","La información es poder."]}
 ], qs:[
  {q:"Complete: My uncle is ill; he's been in ____ hospital for a week.", a:"no article (in hospital)"},
  {q:"Difference: 'few' vs 'a few'?", a:"few = casi ninguno (negativo); a few = algunos (positivo)."},
  {q:"Correct: The nature is beautiful in Wales.", a:"Nature is beautiful in Wales."}
 ] },

{ cat:"Grammar: Structures", type:"Structures", lvl:"C2", icon:"📍", t:"Fixed Prepositional Phrases and Subtle Prepositions", es:"Locuciones preposicionales y preposiciones sutiles", d:"Preposiciones que cambian de sentido o forman bloques fijos en inglés formal.",
 boxes:[
  {e:"📌", h:"Prepositional blocks", es:"Bloques fijos", i:[["in accordance with, in compliance with","de conformidad con, en cumplimiento de"],["with regard to, in respect of","con respecto a, en lo que respecta a"],["by virtue of, on behalf of","en virtud de, en nombre de"]], ex:["We acted in accordance with the rules.","Actuamos conforme a las normas."]},
  {e:"🔀", h:"Prepositions that change meaning", es:"Preposiciones que cambian el sentido", i:[["at the end vs in the end","al final (punto físico) vs finalmente"],["in the way vs on the way","estorbando vs de camino"],["beside vs besides","junto a vs además de"]], ex:["In the end, they settled out of court.","Al final, llegaron a un acuerdo extrajudicial."]},
  {e:"⏱️", h:"Time: by, until, within", es:"Tiempo: by, until, within", i:[["by Friday (no later than)","para el viernes (a más tardar)"],["until Friday (continuing)","hasta el viernes (de forma continua)"],["within a week; in a week","en el plazo de una semana; dentro de una semana"]], ex:["Submit the form by noon.","Entrega el formulario antes del mediodía."]},
  {e:"🧱", h:"Adjective + preposition", es:"Adjetivo + preposición", i:[["oblivious to, impervious to","ajeno a, impermeable a"],["averse to, amenable to","reacio a, receptivo a"],["conducive to, prone to","propicio a, propenso a"]], ex:["He's averse to taking risks.","Es reacio a correr riesgos."]},
  {e:"🔄", h:"Preposition stranding vs pied-piping", es:"Preposición al final vs al inicio", i:[["Who did you speak to?","¿Con quién hablaste?"],["To whom did you speak? (formal)","¿Con quién habló? (formal)"],["The man I spoke to / the man to whom I spoke","El hombre con quien hablé"]], ex:["The firm for which she works is based in Leeds.","La firma para la que trabaja tiene sede en Leeds."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ in regard of this matter","✓ with regard to this matter — la fórmula fija es with regard to"],["✗ different than (in formal BrE)","✓ different from / to — British prefers from or to"],["✗ He is oblivious about the danger.","✓ He is oblivious to / of the danger. — oblivious no lleva 'about'; 'to' es más habitual."]], ex:["Pursuant to clause 4, the fee is due.","De conformidad con la cláusula 4, la tarifa es exigible."]}
 ], qs:[
  {q:"Complete: He is not amenable ____ change.", a:"to"},
  {q:"Which means 'no later than': by Friday or until Friday?", a:"by Friday"},
  {q:"Correct: in regard of your letter (formal).", a:"with regard to your letter"}
 ] },

{ cat:"Vocabulary: Everyday Life", type:"Vocabulary", lvl:"C2", icon:"👁️", t:"Look, Glance, Gaze, Glimpse: Verbs of Seeing", es:"Look, glance, gaze, glimpse: verbos de ver", d:"Matices precisos entre verbos de mirada: duración, intención y emoción.",
 boxes:[
  {e:"⚡", h:"Brief looks", es:"Miradas breves", i:[["steal a glance: look quickly and secretly","steal a glance: mirar de reojo, a escondidas"],["glimpse: a partial or fleeting sight","glimpse: ver fugazmente o a medias"],["peek / peep: a furtive look","peek / peep: mirada furtiva"]], ex:["I caught a glimpse of the King's car.","Vislumbré el coche del Rey."]},
  {e:"🔭", h:"Wide-eyed and absorbed looks", es:"Miradas asombradas o absortas", i:[["goggle: stare wide-eyed in amazement","goggle: mirar con ojos como platos"],["gawp / gawk: stare stupidly (informal)","gawp / gawk: mirar con la boca abierta (informal)"],["pore over: study intently","pore over: estudiar con atención minuciosa"]], ex:["The children goggled at the fireworks.","Los niños miraron boquiabiertos los fuegos artificiales."]},
  {e:"🔎", h:"Careful examination", es:"Examen cuidadoso", i:[["scrutinise: examine closely","scrutinise: examinar con detalle"],["peruse: read or examine carefully","peruse: leer con atención"],["vet: check carefully before approving","vet: someter a revisión minuciosa"]], ex:["She perused the contract line by line.","Leyó el contrato línea por línea."]},
  {e:"😠", h:"Emotional looks", es:"Miradas emocionales", i:[["scowl: look with a frown of displeasure","scowl: mirar con el ceño fruncido"],["leer: look in an unpleasant sexual way","leer: mirar con lascivia"],["ogle: look at with desire","ogle: comerse con los ojos"]], ex:["He scowled at me across the table.","Me miró con el ceño fruncido desde el otro lado de la mesa."]},
  {e:"🤏", h:"Narrowed and suspicious looks", es:"Miradas entornadas y recelosas", i:[["squint: eyes half-closed against light","squint: entrecerrar los ojos por la luz"],["peer: look hard, as if unable to see well","peer: mirar con esfuerzo, como quien ve mal"],["eye / eyeball: watch suspiciously","eye / eyeball: mirar con recelo"]], ex:["She squinted into the sun.","Entrecerró los ojos contra el sol."]},
  {e:"🧠", h:"Metaphorical seeing", es:"Ver en sentido figurado", i:[["discern: perceive with difficulty","discern: percibir con dificultad"],["behold: see (literary)","behold: contemplar (literario)"],["witness: see an event","witness: presenciar un hecho"]], ex:["It is hard to discern any logic in the plan.","Es difícil discernir lógica alguna en el plan."]}
 ], qs:[
  {q:"Which verb: a fleeting, partial sight of something?", a:"glimpse"},
  {q:"Which verb means 'stare wide-eyed in amazement'?", a:"goggle"},
  {q:"Complete: She spent hours poring ____ the old maps.", a:"over"}
 ] },

{ cat:"Vocabulary: Everyday Life", type:"Vocabulary", lvl:"C2", icon:"🗯️", t:"Verbs of Speaking: From Murmur to Bellow", es:"Verbos de habla: de murmurar a bramar", d:"Verbos que expresan volumen, actitud y manera de hablar, muy usados en literatura.",
 boxes:[
  {e:"🤫", h:"Quiet speech", es:"Habla baja", i:[["hiss: speak in a sharp, angry whisper","hiss: decir con un siseo furioso"],["intone: speak in a solemn, level voice","intone: entonar con voz solemne y monótona"],["mumble: speak unclearly","mumble: farfullar"]], ex:["She hissed a warning in his ear.","Le siseó una advertencia al oído."]},
  {e:"📣", h:"Loud speech", es:"Habla fuerte", i:[["bellow: shout deeply and angrily","bellow: bramar"],["bawl: shout loudly and coarsely","bawl: gritar con vulgaridad"],["holler: shout (informal)","holler: gritar (informal)"]], ex:["The sergeant bellowed an order.","El sargento bramó una orden."]},
  {e:"😒", h:"Complaining and criticising", es:"Quejarse y criticar", i:[["grumble / grouse: complain mildly","grumble / grouse: quejarse"],["carp: complain about trivialities","carp: criticar por nimiedades"],["whinge: complain in an annoying way (BrE)","whinge: lloriquear (BrE)"]], ex:["Stop whingeing and get on with it.","Deja de lloriquear y ponte a ello."]},
  {e:"💬", h:"Talking at length", es:"Hablar largamente", i:[["ramble: talk without clear direction","ramble: divagar"],["rant: talk wildly and angrily","rant: despotricar"],["witter on: talk at length about trivia (BrE)","witter on: parlotear (BrE)"]], ex:["He wittered on about his roses for an hour.","Parloteó una hora sobre sus rosas."]},
  {e:"🤐", h:"Brief and curt speech", es:"Habla breve y seca", i:[["interject: cut in with a remark","interject: intercalar una observación"],["rejoin: answer, often sharply (formal)","rejoin: replicar (formal)"],["quip: make a witty remark","quip: soltar una ocurrencia"]], ex:["'Not at all,' he quipped, 'I'm always late.'","—Para nada —bromeó—, siempre llego tarde."]},
  {e:"🕊️", h:"Gentle persuasion", es:"Persuasión suave", i:[["coax: persuade gently","coax: persuadir con suavidad"],["cajole: persuade by flattery","cajole: engatusar"],["beseech / implore: beg earnestly","beseech / implore: suplicar"]], ex:["He cajoled her into joining the committee.","La engatusó para que se uniera al comité."]}
 ], qs:[
  {q:"Which verb: to complain about petty things?", a:"carp"},
  {q:"Which verb: persuade someone by flattery?", a:"cajole"},
  {q:"Choose: talk at length about nothing, BrE informal.", a:"witter on"}
 ] },

{ cat:"Communication & British Culture", type:"Vocabulary", lvl:"C2", icon:"🔔", t:"Cockney Rhyming Slang", es:"Jerga rimada cockney", d:"El argot rimado del este de Londres, con ejemplos que siguen vivos en el habla diaria.",
 boxes:[
  {e:"🍎", h:"Everyday classics", es:"Clásicos cotidianos", i:[["apples and pears (= stairs)","escaleras"],["dog and bone (= phone)","teléfono"],["plates of meat (= feet)","pies"],["trouble and strife (= wife)","esposa"]], ex:["Pick up the dog and bone, will you?","Contesta el teléfono, ¿quieres?"]},
  {e:"🍺", h:"Pubs and drink", es:"Pubs y bebida", i:[["pig's ear (= beer)","cerveza"],["Rosie Lee (= tea)","té"],["Brahms and Liszt (= pissed, i.e. drunk)","borracho (muy coloquial)"]], ex:["Fancy a cup of Rosie?","¿Quieres un té?"]},
  {e:"💷", h:"Money and trade", es:"Dinero y comercio", i:[["bread and honey (= money)","dinero"],["Lady Godiva (= fiver)","billete de cinco libras"],["Ayrton (Senna) (= tenner)","billete de diez libras"]], ex:["Can you lend me a Lady Godiva?","¿Me prestas cinco libras?"]},
  {e:"🧑", h:"People", es:"Personas", i:[["china (plate) (= mate)","amigo"],["barnet (Fair) (= hair)","pelo"],["tea leaf (= thief)","ladrón"]], ex:["My old china is coming to dinner.","Mi viejo amigo viene a cenar."]},
  {e:"✂️", h:"The rhyme often drops", es:"La rima a menudo se omite", i:[["use your loaf (loaf of bread = head)","usa la cabeza"],["I'm going up the apples (and pears).","Voy a subir las escaleras."],["I'm in a bit of Barney (Rubble) (= trouble).","Estoy metido en un lío."]], ex:["Use your loaf, mate!","¡Usa la cabeza, amigo!"]},
  {e:"🎭", h:"Register and use", es:"Registro y uso", i:[["Informal; strongly London.","Informal; muy londinense."],["Used for humour and local colour.","Se usa por humor y color local."],["Learners should recognise, not overuse it.","El estudiante debe reconocerlo, no abusar."]], ex:["He's a proper Cockney, he is.","Es un cockney de pura cepa."]}
 ], qs:[
  {q:"What does 'apples and pears' mean?", a:"Stairs (escaleras)."},
  {q:"What is a 'tea leaf' in Cockney?", a:"A thief (ladrón)."},
  {q:"What does 'use your loaf' mean?", a:"Use your head (usa la cabeza)."}
 ] },

{ cat:"Communication & British Culture", type:"Vocabulary", lvl:"C2", icon:"🗺️", t:"Regional Britishisms: Scots, Geordie and Scouse", es:"Regionalismos británicos: escocés, geordie y scouse", d:"Palabras de Escocia, Newcastle y Liverpool que aparecen en la prensa y la televisión.",
 boxes:[
  {e:"🏴󠁧󠁢󠁳󠁣󠁴󠁿", h:"Scots words", es:"Palabras escocesas", i:[["wee (= small)","pequeño"],["bairn (= child)","niño"],["dreich (= dull, wet and grey)","gris, húmedo y triste (clima)"],["braw (= fine, splendid)","estupendo"]], ex:["It's a dreich day in Glasgow.","Es un día gris y lluvioso en Glasgow."]},
  {e:"🏘️", h:"More Scots", es:"Más palabras escocesas", i:[["ken (= know)","saber"],["outwith (= outside of)","fuera de"],["glaikit (= silly, vacant)","bobo, distraído"]], ex:["Dinnae fash yersel'.","No te preocupes."]},
  {e:"⚫", h:"Geordie (Newcastle)", es:"Geordie (Newcastle)", i:[["howay (= come on)","vamos, ándale"],["canny (= good, nice; not 'careful')","bueno, agradable"],["bonny (= pretty, healthy-looking)","bonito, de buen aspecto"],["divvy (= idiot)","tonto"]], ex:["Howay, man, we'll be late!","¡Vamos, que llegaremos tarde!"]},
  {e:"🎸", h:"Scouse (Liverpool)", es:"Scouse (Liverpool)", i:[["boss (= excellent)","excelente"],["lid (= child, kid)","niño"],["la (= mate, pal)","amigo, colega"],["sound (= great, fine; 'sound' = OK)","genial, de acuerdo"]], ex:["That's boss, la!","¡Eso es genial, amigo!"]},
  {e:"🪨", h:"Other regional markers", es:"Otros marcadores regionales", i:[["nowt, owt (= nothing, anything; North)","nada, algo (norte de Inglaterra)"],["mither (= pester or fuss; North)","molestar, agobiar"],["bampot (= fool; Scots)","tonto, idiota"]], ex:["There's nowt wrong with it.","No tiene nada de malo."]},
  {e:"🧠", h:"Usage advice", es:"Consejos de uso", i:[["Recognise them; don't imitate lightly.","Reconócelas; no las imites a la ligera."],["Many are informal or affectionate.","Muchas son informales o afectuosas."],["Context decides if they offend.","El contexto decide si ofenden."]], ex:["Dialect words give texture to British speech.","Los dialectalismos dan textura al habla británica."]}
 ], qs:[
  {q:"What does 'dreich' describe?", a:"Weather that is dull, wet and grey (Scots)."},
  {q:"Where is 'howay' typically used?", a:"Newcastle (Geordie): 'come on'."},
  {q:"What does 'nowt' mean?", a:"Nothing (Northern English)."}
 ] },

{ cat:"Vocabulary: Work, Study & Society", type:"Vocabulary", lvl:"C2", icon:"🏛️", t:"Latin and Greek Roots in Learned English", es:"Raíces latinas y griegas en el inglés culto", d:"Raíces que ayudan a deducir el significado de palabras abstractas y técnicas.",
 boxes:[
  {e:"👁️", h:"spec / vid: to see", es:"spec / vid: ver", i:[["spectator, retrospective, perspective","espectador, retrospectivo, perspectiva"],["evidence, provide, revise","evidencia, proveer, revisar"],["introspection: looking inward","introspección: mirar hacia dentro"]], ex:["A retrospective of his work opens today.","Hoy se inaugura una retrospectiva de su obra."]},
  {e:"✍️", h:"scrib / graph: to write", es:"scrib / graph: escribir", i:[["prescribe, subscribe, transcribe","prescribir, suscribirse, transcribir"],["calligraphy, biography, graphology","caligrafía, biografía, grafología"],["inscription, manuscript","inscripción, manuscrito"]], ex:["The doctor prescribed antibiotics.","El médico recetó antibióticos."]},
  {e:"🏃", h:"duc / ced: lead, go", es:"duc / ced: llevar, ir", i:[["conduct, induce, deduce","conducir, inducir, deducir"],["precede, recede, concede","preceder, retroceder, conceder"],["unprecedented: never before","sin precedentes"]], ex:["The results were unprecedented.","Los resultados no tenían precedentes."]},
  {e:"⚖️", h:"jud / leg / jur: law", es:"jud / leg / jur: ley", i:[["judicial, prejudice, adjudicate","judicial, prejuicio, adjudicar"],["legitimate, legislate, delegate","legítimo, legislar, delegar"],["jurisdiction, perjury","jurisdicción, perjurio"]], ex:["The court has no jurisdiction here.","El tribunal no tiene jurisdicción aquí."]},
  {e:"🌀", h:"Greek: pan, poly, anthropo", es:"Griego: pan, poly, anthropo", i:[["pandemic, panacea, panorama","pandemia, panacea, panorama"],["polyglot, polygamy, polymath","políglota, poligamia, erudito"],["philanthropist, misanthrope","filántropo, misántropo"]], ex:["Leonardo was a true polymath.","Leonardo fue un verdadero erudito."]},
  {e:"🔍", h:"False friends from roots", es:"Falsos amigos de raíz común", i:[["sensible = prudent, not 'sensitive'","sensible en inglés = sensato; sensitive = sensible"],["eventually ≠ eventualmente = finally","eventually = finalmente"],["actually ≠ actualmente = in fact","actually = en realidad"]], ex:["She's a sensible woman.","Es una mujer sensata."]}
 ], qs:[
  {q:"What does the root 'spec' mean?", a:"Ver / mirar (to see)."},
  {q:"Which word means 'knowing many languages'?", a:"polyglot"},
  {q:"What does 'eventually' mean?", a:"Finalmente / con el tiempo (not 'eventualmente')."}
 ] },

{ cat:"Vocabulary: Work, Study & Society", type:"Vocabulary", lvl:"C2", icon:"⚔️", t:"Germanic vs Latinate Doublets", es:"Dobletes germánicos y latinos", d:"Pares como ask/enquire: la palabra anglosajona es cercana y la latina más formal.",
 boxes:[
  {e:"🛡️", h:"Everyday vs formal verbs", es:"Verbos cotidianos y formales", i:[["ask → enquire / inquire","preguntar → indagar / consultar"],["start → commence","empezar → comenzar"],["help → assist / aid","ayudar → asistir / auxiliar"],["buy → purchase","comprar → adquirir"]], ex:["Applicants should enquire at reception.","Los solicitantes deben preguntar en recepción."]},
  {e:"🍖", h:"The animal/meat divide", es:"Animal y carne", i:[["cow → beef, pig → pork","vaca → carne de res, cerdo → carne de cerdo"],["sheep → mutton, deer → venison","oveja → carne de oveja, ciervo → venado"],["Saxon farmers, Norman diners","Los campesinos sajones, los comensales normandos"]], ex:["We had venison at the banquet.","Comimos venado en el banquete."]},
  {e:"💭", h:"Nouns: feeling vs register", es:"Sustantivos: sentimiento y registro", i:[["wish → desire","deseo, ganas → deseo formal"],["freedom → liberty","libertad cotidiana → libertad política"],["kingly → royal → regal","propio de un rey → real → regio"]], ex:["Liberty is more than freedom from restraint.","La libertad es más que ausencia de restricciones."]},
  {e:"🏗️", h:"Impact on tone", es:"Efecto en el tono", i:[["Germanic words feel warm, direct.","Las palabras germánicas suenan cálidas y directas."],["Latinate words feel distant, official.","Las latinas suenan distantes y oficiales."],["Churchill: 'blood, toil, tears and sweat'","Churchill: 'sangre, esfuerzo, lágrimas y sudor'"]], ex:["'We shall fight on the beaches.'","'Lucharemos en las playas.'"]},
  {e:"🔨", h:"Phrasal verbs vs Latin verbs", es:"Phrasal verbs y verbos latinos", i:[["put off → postpone","aplazar"],["go on → continue","continuar"],["find out → ascertain","averiguar"],["give up → relinquish","renunciar"]], ex:["The committee postponed the vote.","El comité aplazó la votación."]},
  {e:"🎯", h:"Choosing wisely", es:"Elegir con criterio", i:[["Speech: prefer Germanic.","Habla: mejor lo germánico."],["Legal text: Latinate suits.","Textos legales: lo latino encaja."],["Overuse sounds pompous.","El exceso suena pomposo."]], ex:["Say 'use', not 'utilise', in most cases.","Di 'use', no 'utilise', en la mayoría de los casos."]}
 ], qs:[
  {q:"Formal equivalent of 'buy'?", a:"purchase"},
  {q:"Why do we have 'pork' and 'pig'?", a:"Pig (sajón, el animal); pork (francés normando, la carne)."},
  {q:"Formal equivalent of 'find out'?", a:"ascertain"}
 ] },

{ cat:"Vocabulary: Work, Study & Society", type:"Vocabulary", lvl:"C2", icon:"🔀", t:"Easily Confused Words at the Highest Level", es:"Palabras que se confunden incluso a nivel avanzado", d:"Pares como principle/principal, imply/infer o discreet/discrete que ponen a prueba a los nativos.",
 boxes:[
  {e:"🧭", h:"principle / principal", es:"principle / principal", i:[["principle: a rule or belief","principle: principio"],["principal: main; head of a school","principal: principal; director"],["on principle; in principle","por principio; en principio"]], ex:["She refused on principle.","Se negó por principio."]},
  {e:"💬", h:"imply / infer", es:"imply / infer", i:[["The speaker implies.","El que habla insinúa."],["The listener infers.","El que escucha deduce."],["What are you implying?","¿Qué insinúas?"]], ex:["I inferred from his silence that he was angry.","Deduje de su silencio que estaba enojado."]},
  {e:"🤫", h:"discreet / discrete", es:"discreet / discrete", i:[["discreet: tactful, careful","discreet: discreto"],["discrete: separate, distinct","discrete: separado, distinto"],["a discreet enquiry","una consulta discreta"]], ex:["The system has three discrete stages.","El sistema tiene tres etapas diferenciadas."]},
  {e:"🧪", h:"affect / effect", es:"affect / effect", i:[["affect (verb): influence","affect: afectar"],["effect (noun): result","effect: efecto"],["effect (verb): bring about","effect: llevar a cabo"]], ex:["The minister effected a major change.","El ministro llevó a cabo un gran cambio."]},
  {e:"👀", h:"disinterested / uninterested", es:"disinterested / uninterested", i:[["disinterested: impartial","disinterested: imparcial"],["uninterested: not interested","uninterested: sin interés, indiferente"],["a disinterested judge","un juez imparcial"]], ex:["We need a disinterested arbitrator.","Necesitamos un árbitro imparcial."]},
  {e:"🌡️", h:"continual / continuous", es:"continual / continuous", i:[["continual: repeated, with pauses","continual: repetido"],["continuous: without interruption","continuous: sin interrupción"],["continual complaints; continuous rain","quejas reiteradas; lluvia ininterrumpida"]], ex:["The continual interruptions annoyed her.","Las constantes interrupciones la molestaron."]}
 ], qs:[
  {q:"Complete: The listener ____ (imply/infer) meaning.", a:"infers"},
  {q:"Which means 'impartial': disinterested or uninterested?", a:"disinterested"},
  {q:"Which means 'separate': discreet or discrete?", a:"discrete"}
 ] },

{ cat:"Communication & British Culture", type:"Vocabulary", lvl:"C2", icon:"🎭", t:"Euphemism, Spin and Doublespeak", es:"Eufemismo, spin y lenguaje evasivo", d:"Cómo el lenguaje suaviza o disfraza realidades en política, empresa y vida social.",
 boxes:[
  {e:"⚰️", h:"Military and official euphemism", es:"Eufemismo militar y oficial", i:[["friendly fire = killing your own side","fuego amigo = matar a los propios"],["enhanced interrogation = torture","interrogatorio mejorado = tortura"],["a surgical strike = a bombing raid","ataque quirúrgico = bombardeo"]], ex:["The report blamed friendly fire for the deaths.","El informe atribuyó las muertes al fuego amigo."]},
  {e:"💼", h:"Corporate spin", es:"Eufemismos corporativos", i:[["negative growth = decline","crecimiento negativo = caída"],["a career-limiting move = a blunder","un movimiento limitante de carrera = una metedura de pata"],["a sub-optimal outcome = a failure","un resultado subóptimo = un fracaso"]], ex:["Sales showed negative growth last quarter.","Las ventas mostraron un crecimiento negativo el último trimestre."]},
  {e:"🏛️", h:"Political language", es:"Lenguaje político", i:[["a terminological inexactitude = a lie (Churchill)","una inexactitud terminológica = una mentira (Churchill)"],["a full and frank exchange of views = a row","un intercambio franco de opiniones = una pelea"],["a courageous decision (Yes, Minister) = political suicide","una decisión valiente (Yes, Minister) = suicidio político"]], ex:["The talks involved a full and frank exchange of views.","Las conversaciones incluyeron un franco intercambio de opiniones."]},
  {e:"🚻", h:"Estate-agent and everyday spin", es:"Eufemismos de inmobiliaria y cotidianos", i:[["cosy = tiny","acogedor = diminuto"],["deceptively spacious = small","engañosamente amplio = pequeño"],["a property with character = in need of repair","una propiedad con carácter = que necesita reformas"]], ex:["The flat is cosy, which means you can touch both walls.","El piso es acogedor, es decir, tocas las dos paredes con los brazos abiertos."]},
  {e:"🧼", h:"Orwell and Newspeak", es:"Orwell y la neolengua", i:[["Newspeak: language shrunk to limit thought (1984)","neolengua: lenguaje reducido para limitar el pensamiento (1984)"],["Ministry of Peace = ministry of war","Ministerio de la Paz = ministerio de la guerra"],["Doublethink: holding two contradictory beliefs","doblepensar: sostener dos creencias contradictorias"]], ex:["'War is peace' is the classic piece of doublespeak.","'La guerra es la paz' es el ejemplo clásico de doble lenguaje."]},
  {e:"🔦", h:"Non-denials and evasive formulae", es:"Evasivas y fórmulas para no responder", i:[["I can neither confirm nor deny it.","No puedo confirmarlo ni negarlo."],["Lessons will be learned.","Se sacarán lecciones."],["I'm not going to comment on speculation.","No voy a comentar las especulaciones."]], ex:["Lessons will be learned, the minister said.","Se sacarán lecciones, dijo el ministro."]}
 ], qs:[
  {q:"What does 'friendly fire' mean?", a:"Being killed by your own side's weapons (fuego amigo)."},
  {q:"What did Churchill mean by a 'terminological inexactitude'?", a:"A lie (una mentira)."},
  {q:"What does an estate agent mean by 'cosy'?", a:"Very small (diminuto)."}
 ] },

{ cat:"Phrasal Verbs, Idioms & Collocations", type:"Expressions", lvl:"C2", icon:"📖", t:"Proverbs and Sayings in Use", es:"Refranes y dichos en uso", d:"Refranes ingleses, a menudo abreviados, y cómo usarlos con ironía o sutileza.",
 boxes:[
  {e:"⏰", h:"Proverbs of caution", es:"Refranes de cautela", i:[["Don't count your chickens before they hatch.","No vendas la piel del oso antes de cazarlo."],["Once bitten, twice shy.","Gato escaldado del agua fría huye."],["Let sleeping dogs lie.","Mejor no menear el asunto."]], ex:["I'd let sleeping dogs lie.","Yo no removería el asunto."]},
  {e:"🤝", h:"Human nature", es:"Naturaleza humana", i:[["A leopard cannot change its spots.","Genio y figura hasta la sepultura."],["Familiarity breeds contempt.","La confianza da asco."],["Pride comes before a fall.","La soberbia precede a la caída."]], ex:["Familiarity breeds contempt, as they say.","La confianza da asco, como dicen."]},
  {e:"🍀", h:"Cutting your losses", es:"Asumir las pérdidas", i:[["There's no use crying over spilt milk.","A lo hecho, pecho."],["Don't throw good money after bad.","No tires más dinero en un mal negocio."],["Don't lock the stable door after the horse has bolted.","No cierres el establo cuando el caballo ya se escapó."]], ex:["It's spilt milk now; let's move on.","Ya está hecho; sigamos adelante."]},
  {e:"🌧️", h:"Hypocrisy, envy and excuses", es:"Hipocresía, envidia y excusas", i:[["The pot calling the kettle black.","El burro hablando de orejas."],["The grass is always greener on the other side.","El césped del vecino siempre parece más verde."],["A bad workman blames his tools.","Al mal obrero le estorban las herramientas."]], ex:["You complaining about noise? That's the pot calling the kettle black.","¿Tú quejándote del ruido? Es el burro hablando de orejas."]},
  {e:"🗣️", h:"Silence and speech", es:"Silencio y palabra", i:[["Least said, soonest mended.","Cuanto menos se diga, antes se arregla."],["Walls have ears.","Las paredes oyen."],["Speech is silver, silence is golden.","La palabra es plata; el silencio, oro."]], ex:["Walls have ears, so keep your voice down.","Las paredes oyen, así que baja la voz."]},
  {e:"🎯", h:"Using proverbs with finesse", es:"Usar refranes con tino", i:[["Often shortened: 'Well, once bitten...'","A menudo se abrevian: 'Bueno, gato escaldado...'"],["Many contradict each other: 'Look before you leap' / 'He who hesitates is lost'.","Muchos se contradicen entre sí."],["Overuse sounds clichéd.","El exceso suena a tópico."]], ex:["Well, you know what they say...","Bueno, ya sabes lo que dicen..."]}
 ], qs:[
  {q:"Complete: Once bitten, twice ____.", a:"shy"},
  {q:"Complete: Pride comes before a ____.", a:"fall"},
  {q:"Complete: A leopard cannot change its ____.", a:"spots"}
 ] },

{ cat:"Communication & British Culture", type:"Expressions", lvl:"C2", icon:"🫖", t:"Understatement and British Irony", es:"Atenuación e ironía británica", d:"Decir menos de lo que se piensa: lítotes, sarcasmo seco y cómo interpretarlo.",
 boxes:[
  {e:"😐", h:"Classic understatement", es:"Atenuaciones clásicas", i:[["Not bad = very good","Not bad = muy bueno"],["A bit of a problem = a disaster","Un pequeño problema = un desastre"],["Quite good = fairly good (BrE)","Quite good = bastante bueno"]], ex:["It's a bit damp out there.","Está un poco húmedo ahí fuera."]},
  {e:"🌪️", h:"Said when the opposite is true", es:"Decir lo contrario", i:[["Lovely weather! (in a downpour)","¡Qué clima precioso! (bajo la lluvia)"],["Well, that went well. (it didn't)","Pues salió bien. (no fue así)"],["Thanks a bunch!","¡Muchas gracias! (irónico)"]], ex:["Oh, brilliant. Another delay.","Oh, genial. Otro retraso."]},
  {e:"🧐", h:"Polite warning signs", es:"Avisos corteses", i:[["With respect... = I disagree","With respect... = no estoy de acuerdo"],["I hear what you say = I disagree","I hear what you say = no te daré la razón"],["That's brave! = foolish","¡Qué valiente! = una locura"]], ex:["With the greatest respect, Minister...","Con el mayor de los respetos, ministro..."]},
  {e:"🔥", h:"Dry sarcasm", es:"Sarcasmo seco", i:[["Don't strain yourself.","No te esfuerces demasiado."],["I'm sure that'll end well.","Seguro que acaba bien."],["Oh, you shouldn't have.","No debiste molestarte."]], ex:["Well, that's helpful. Thanks.","Pues qué útil. Gracias."]},
  {e:"🔔", h:"Signals of irony", es:"Señales de ironía", i:[["Deadpan tone, no smile","Tono inexpresivo, sin sonreír"],["Stress on one word: 'lovely'","Énfasis en una palabra"],["Context contradicts words","El contexto contradice las palabras"]], ex:["Marvellous. Just marvellous.","Maravilloso. Simplemente maravilloso."]},
  {e:"🧭", h:"Decoding for learners", es:"Descifrar para estudiantes", i:[["Check tone and situation.","Fíjate en el tono y la situación."],["Praise may be criticism.","El elogio puede ser crítica."],["Reply lightly; don't take offence.","Responde con ligereza."]], ex:["That's one way of looking at it.","Es una forma de verlo."]}
 ], qs:[
  {q:"What does 'I hear what you say' often mean?", a:"I disagree (no estoy de acuerdo)."},
  {q:"What does 'That's brave' hint?", a:"That it is foolish or risky."},
  {q:"What does 'a bit of a problem' often mean?", a:"A serious problem (understatement)."}
 ] },

{ cat:"Phrasal Verbs, Idioms & Collocations", type:"Expressions", lvl:"C2", icon:"🧵", t:"Rare Multi-word Verbs", es:"Verbos compuestos poco frecuentes", d:"Phrasal y prepositional verbs de registro alto que usan los hablantes cultos.",
 boxes:[
  {e:"🌫️", h:"Disappear and fade", es:"Desaparecer y desvanecerse", i:[["peter out: gradually end","peter out: ir extinguiéndose"],["fizzle out: end weakly","fizzle out: quedar en nada"],["tail off: decline gradually","tail off: decaer gradualmente"]], ex:["The protest petered out by midnight.","La protesta se fue apagando hacia medianoche."]},
  {e:"🤐", h:"Concealing and revealing", es:"Ocultar y revelar", i:[["gloss over: treat superficially","gloss over: tratar de pasada"],["let on: reveal a secret","let on: dejar entrever"],["smoke out: force into the open","smoke out: sacar a la luz"]], ex:["He never let on that he knew.","Nunca dejó ver que lo sabía."]},
  {e:"💥", h:"Conflict", es:"Conflicto", i:[["fall out (with): quarrel","fall out: pelearse"],["lash out (at): attack suddenly","lash out: arremeter"],["square up to: confront","square up to: encararse"]], ex:["She lashed out at the press.","Arremetió contra la prensa."]},
  {e:"🧱", h:"Support and endure", es:"Apoyar y aguantar", i:[["bear out: confirm","bear out: corroborar"],["see through: support to the end","see through: llevar a término"],["tough out: endure stubbornly","tough out: aguantar con firmeza"]], ex:["The facts bear out his claim.","Los hechos corroboran su afirmación."]},
  {e:"🔧", h:"Dealing with things", es:"Resolver asuntos", i:[["iron out: resolve small problems","iron out: resolver pequeños problemas"],["thrash out: settle through long debate","thrash out: acordar tras mucho debate"],["hammer out: agree with effort","hammer out: acordar con esfuerzo"]], ex:["They thrashed out a deal overnight.","Acordaron un trato durante la noche."]},
  {e:"🧠", h:"Thinking and deciding", es:"Pensar y decidir", i:[["mull over: think carefully","mull over: reflexionar"],["tease out: extract with care","tease out: extraer con cuidado"],["hark back to: recall the past","hark back to: remontarse a"]], ex:["Let me mull it over.","Déjame darle vueltas."]}
 ], qs:[
  {q:"Which verb: attack suddenly, in words or blows?", a:"lash out"},
  {q:"Which verb: confirm that something is true?", a:"bear out"},
  {q:"Which verb: resolve small problems?", a:"iron out"}
 ] },

{ cat:"Phrasal Verbs, Idioms & Collocations", type:"Expressions", lvl:"C2", icon:"✍️", t:"Collocations for Formal and Academic Prose", es:"Colocaciones para prosa formal y académica", d:"Combinaciones de palabras que dan precisión y naturalidad a un texto formal.",
 boxes:[
  {e:"🧪", h:"Evidence and argument", es:"Pruebas y argumentos", i:[["compelling evidence","pruebas convincentes"],["a cogent argument","un argumento sólido"],["draw a conclusion","sacar una conclusión"],["substantiate a claim","fundamentar una afirmación"]], ex:["The data lend weight to the theory.","Los datos refuerzan la teoría."]},
  {e:"📈", h:"Change and trends", es:"Cambio y tendencias", i:[["a marked improvement","una mejora notable"],["a precipitous decline","un descenso abrupto"],["gain momentum","ganar impulso"]], ex:["Support for the policy has gained momentum.","El apoyo a la política ha ganado impulso."]},
  {e:"⚖️", h:"Responsibility and risk", es:"Responsabilidad y riesgo", i:[["bear responsibility","asumir la responsabilidad"],["pose a threat","representar una amenaza"],["mitigate the risk","mitigar el riesgo"]], ex:["The scheme poses serious risks.","El plan implica riesgos serios."]},
  {e:"🎓", h:"Research language", es:"Lenguaje de investigación", i:[["conduct research","realizar una investigación"],["yield results","dar resultados"],["shed light on","arrojar luz sobre"]], ex:["The study sheds light on sleep.","El estudio arroja luz sobre el sueño."]},
  {e:"🌐", h:"Society and policy", es:"Sociedad y política", i:[["widespread concern","preocupación generalizada"],["implement a policy","aplicar una política"],["exert influence","ejercer influencia"]], ex:["The government exerted pressure on banks.","El gobierno presionó a los bancos."]},
  {e:"🚫", h:"Common collocation errors", es:"Errores de colocación", i:[["✗ do a research","✓ carry out research — 'research' es incontable."],["✗ rise a question","✓ raise a question — raise es transitivo (plantear); rise no lleva objeto."],["✗ do a mistake","✓ make a mistake — mistake va con make."]], ex:["The report raises serious concerns.","El informe plantea serias preocupaciones."]}
 ], qs:[
  {q:"Complete: The study ____ light on the problem.", a:"sheds"},
  {q:"Correct: They did a research.", a:"They did / carried out research. — 'research' es incontable."},
  {q:"Complete: The project has gained ____.", a:"momentum"}
 ] },

{ cat:"Communication & British Culture", type:"Expressions", lvl:"C2", icon:"📰", t:"Register Shift: Legalese, Academese and Journalese", es:"Cambio de registro: lenguaje legal, académico y periodístico", d:"El mismo mensaje en tres registros y cómo reconocerlos y traducirlos.",
 boxes:[
  {e:"⚖️", h:"Legalese", es:"Lenguaje jurídico", i:[["hereinafter, aforesaid, notwithstanding","en lo sucesivo, antedicho, no obstante"],["the party of the first part","la parte de la primera parte"],["null and void; cease and desist","nulo y sin efecto; cesar y desistir"]], ex:["The aforesaid agreement is hereby terminated.","El citado acuerdo queda por la presente rescindido."]},
  {e:"🎓", h:"Academic register", es:"Registro académico", i:[["It could be argued that...","Podría argumentarse que..."],["This paper examines...","Este artículo examina..."],["Findings suggest that...","Los resultados sugieren que..."]], ex:["The evidence would seem to indicate a trend.","Las pruebas parecen indicar una tendencia."]},
  {e:"🗞️", h:"Journalese", es:"Lenguaje periodístico", i:[["probe = investigation; slam = criticise","probe = investigación; slam = criticar"],["bid = attempt; row = quarrel","bid = intento; row = disputa"],["axe = cancel; vow = promise","axe = cancelar; vow = prometer"]], ex:["PM slams rail strike in bid to end row.","El primer ministro critica la huelga ferroviaria en un intento por zanjar la disputa."]},
  {e:"💬", h:"Same message, three registers", es:"Un mensaje, tres registros", i:[["Legal: The tenant shall vacate the premises.","Legal: El inquilino desalojará el inmueble."],["Academic: Tenants are required to leave.","Académico: Se exige a los inquilinos marcharse."],["Press: Tenants given the boot.","Prensa: Echan a los inquilinos."]], ex:["Tenants have been told to leave.","Se ha dicho a los inquilinos que se vayan."]},
  {e:"📉", h:"Nominalisation and passive", es:"Nominalización y pasiva", i:[["Academic: The implementation of the scheme...","La puesta en práctica del plan..."],["Legal: It is hereby agreed that...","Por la presente se acuerda que..."],["Passive hides the agent.","La pasiva oculta al agente."]], ex:["Consideration was given to the proposal.","Se consideró la propuesta."]},
  {e:"🪞", h:"Adjusting for your reader", es:"Adaptarse al lector", i:[["Plain English: short words, active verbs.","Plain English: palabras cortas, verbos activos."],["Never use legalese in an email to a friend.","Nunca uses lenguaje jurídico con un amigo."],["Match tone to audience.","Ajusta el tono al público."]], ex:["Please let me know if you have any questions.","Avísame si tienes preguntas."]}
 ], qs:[
  {q:"Journalese word for 'attempt'?", a:"bid"},
  {q:"Plain-English equivalent of 'notwithstanding'?", a:"despite / in spite of"},
  {q:"Which register: 'The tenant shall vacate the premises'?", a:"Legal (jurídico)."}
 ] },

{ cat:"Communication & British Culture", type:"Expressions", lvl:"C2", icon:"🤹", t:"Puns, Wordplay and Verbal Humour", es:"Juegos de palabras y humor verbal", d:"Dobles sentidos, zeugma, spoonerismos y juegos de palabras en titulares y chistes.",
 boxes:[
  {e:"🔀", h:"Puns and ambiguity", es:"Juegos de palabras y ambigüedad", i:[["I used to be a banker, but I lost interest.","Fui banquero, pero perdí el interés."],["Time flies like an arrow; fruit flies like a banana.","El tiempo vuela como una flecha; a las moscas de la fruta les gusta el plátano."],["A bicycle can't stand on its own: it's two-tyred.","La bici no se sostiene sola: está 'two-tyred' (suena como 'too tired', demasiado cansada)."]], ex:["I'm reading a book on anti-gravity: I can't put it down.","Leo un libro sobre antigravedad: no puedo soltarlo."]},
  {e:"🧷", h:"Zeugma", es:"Zeugma", i:[["She lost her keys and her temper.","Perdió las llaves y la paciencia."],["He took his hat and his leave.","Tomó su sombrero y su despedida."],["Dickens uses zeugma to comic effect.","Dickens lo usa con efecto cómico."]], ex:["He caught a bus and a cold.","Tomó un autobús y pilló un resfriado."]},
  {e:"🔁", h:"Spoonerisms", es:"Spoonerismos", i:[["a half-warmed fish (for a half-formed wish)","'a half-warmed fish' por 'a half-formed wish'"],["You have hissed all my mystery lectures. (for missed my history)","'hissed my mystery lectures' por 'missed my history lectures'"],["named after Rev. William Spooner","nombrado por el reverendo Spooner"]], ex:["a 'tasted worm' for a 'wasted term'","'tasted worm' por 'wasted term'"]},
  {e:"📰", h:"Headline puns", es:"Juegos en titulares", i:[["'Sun-sational' on holiday news","'Sol-pitante' en noticias de vacaciones"],["'Dough-nut worry' about a bakery strike","Juego con 'don't worry'"],["Tabloids love double meanings.","Los tabloides aman los dobles sentidos."]], ex:["Pun-ishment fits the crime.","Juego con 'punishment'."]},
  {e:"🎤", h:"Double entendre", es:"Doble sentido", i:[["Carry On films: innuendo","Las películas Carry On: insinuación"],["Are You Being Served?: innuendo sitcom","Are You Being Served?: comedia de insinuaciones"],["Say no more, nudge nudge.","No digas más, guiño guiño."]], ex:["'Oooh, Matron!' (a Carry On catchphrase)","'¡Oooh, enfermera jefa!' (muletilla de Carry On)"]},
  {e:"🧠", h:"Explaining a pun", es:"Explicar un juego de palabras", i:[["It plays on two meanings of 'interest'.","Juega con dos sentidos de 'interest'."],["The humour depends on sound or sense.","El humor depende del sonido o del sentido."],["Explaining a pun kills it.","Explicar un chiste lo mata."]], ex:["Groan-worthy, but clever.","Para gemir, pero ingenioso."]}
 ], qs:[
  {q:"Name the figure: 'She lost her keys and her temper.'", a:"Zeugma"},
  {q:"What are Spoonerisms?", a:"Intercambio de sonidos iniciales entre palabras."},
  {q:"Joke: 'I used to be a banker but I lost ____.'", a:"interest"}
 ] },

{ cat:"Communication & British Culture", type:"Expressions", lvl:"C2", icon:"🌊", t:"Metaphor and Figurative Language", es:"Metáfora y lenguaje figurado", d:"Sinécdoque, metonimia, personificación, símil y metáforas muertas o vivas en el inglés cotidiano y literario.",
 boxes:[
  {e:"🛞", h:"Synecdoche", es:"Sinécdoque", i:[["All hands on deck! (hands = sailors)","¡Todos a cubierta! (manos = marineros)"],["a new set of wheels (wheels = car)","un coche nuevo (ruedas = coche)"],["the suits (suits = senior managers)","los trajes (= los altos ejecutivos)"]], ex:["Boots on the ground are needed.","Se necesitan soldados sobre el terreno."]},
  {e:"🧭", h:"Oxymoron, paradox and hyperbole", es:"Oxímoron, paradoja e hipérbole", i:[["a deafening silence (oxymoron)","un silencio ensordecedor (oxímoron)"],["Less is more. (paradox)","Menos es más. (paradoja)"],["I've told you a million times. (hyperbole)","Te lo he dicho un millón de veces. (hipérbole)"]], ex:["It was an open secret.","Era un secreto a voces."]},
  {e:"🏛️", h:"Metonymy", es:"Metonimia", i:[["The Crown = the monarchy","The Crown = la monarquía"],["Downing Street = the PM's office","Downing Street = la oficina del primer ministro"],["Fleet Street = the press","Fleet Street = la prensa"]], ex:["Westminster has yet to respond.","Westminster aún no ha respondido."]},
  {e:"👤", h:"Personification", es:"Personificación", i:[["The wind whispered through the trees.","El viento susurró entre los árboles."],["Time marches on.","El tiempo avanza."],["The sea was angry.","El mar estaba furioso."]], ex:["Fortune smiled on her.","La fortuna le sonrió."]},
  {e:"💎", h:"Simile and metaphor", es:"Símil y metáfora", i:[["as cold as ice (simile)","frío como el hielo (símil)"],["Her heart is a stone. (metaphor)","Su corazón es una piedra. (metáfora)"],["Mixed metaphors clash.","Las metáforas mezcladas chocan."]], ex:["He's a rock in a storm.","Es una roca en la tormenta."]},
  {e:"💀", h:"Dead and fresh metaphors", es:"Metáforas muertas y vivas", i:[["Dead: the leg of a table","Muerta: la pata de una mesa"],["Fresh: a river of light","Viva: un río de luz"],["Cliché: at the end of the day","Cliché: al final del día"]], ex:["Let's not reinvent the wheel.","No reinventemos la rueda."]}
 ], qs:[
  {q:"What figure is 'Downing Street announced...'?", a:"Metonymy (metonimia)."},
  {q:"What figure: 'The wind whispered'?", a:"Personification (personificación)."},
  {q:"Is 'the leg of a table' a dead or fresh metaphor?", a:"Dead (muerta)."}
 ] },

{ cat:"Communication & British Culture", type:"Expressions", lvl:"C2", icon:"🪶", t:"Quotations from Great British Writers", es:"Citas de grandes escritores británicos", d:"Citas breves de dominio público de Shakespeare, Austen, Dickens y Wilde, y cómo se usan.",
 boxes:[
  {e:"🎭", h:"Shakespeare", es:"Shakespeare", i:[["To be, or not to be, that is the question.","Ser o no ser, esa es la cuestión."],["All that glisters is not gold. (modern: glitters)","No todo lo que brilla es oro. (hoy: glitters)"],["The course of true love never did run smooth.","El curso del amor verdadero nunca fue tranquilo."]], ex:["Brevity is the soul of wit.","La brevedad es el alma del ingenio."]},
  {e:"💍", h:"Jane Austen", es:"Jane Austen", i:[["It is a truth universally acknowledged...","Es una verdad universalmente reconocida..."],["...that a single man in possession of a good fortune must be in want of a wife.","...que un hombre soltero con fortuna necesita esposa."],["Pride and Prejudice (1813)","Orgullo y prejuicio (1813)"]], ex:["It is a truth universally acknowledged that the bus is late.","Es una verdad universal que el autobús llega tarde."]},
  {e:"🎩", h:"Charles Dickens", es:"Charles Dickens", i:[["It was the best of times, it was the worst of times.","Era el mejor de los tiempos, era el peor de los tiempos."],["Please, sir, I want some more.","Por favor, señor, quiero más."],["A Tale of Two Cities (1859)","Historia de dos ciudades (1859)"]], ex:["Barkis is willing.","Barkis está dispuesto."]},
  {e:"🌹", h:"Oscar Wilde (Irish-born)", es:"Oscar Wilde (nacido en Irlanda)", i:[["I can resist everything except temptation.","Puedo resistir todo menos la tentación."],["We are all in the gutter, but some of us are looking at the stars.","Todos estamos en el arroyo, pero algunos miran las estrellas."],["The truth is rarely pure and never simple.","La verdad rara vez es pura y nunca es simple."]], ex:["The only way to get rid of a temptation is to yield to it.","La única manera de librarse de una tentación es ceder a ella."]},
  {e:"🌍", h:"John Donne and Keats", es:"John Donne y Keats", i:[["No man is an island.","Ningún hombre es una isla."],["A thing of beauty is a joy for ever.","Una cosa bella es un gozo para siempre."],["Death, be not proud.","Muerte, no te enorgullezcas."]], ex:["Any man's death diminishes me.","La muerte de cualquier hombre me disminuye."]},
  {e:"💡", h:"Quoting with style", es:"Citar con estilo", i:[["Allude: 'to be or not to be' as a quick shared reference","Aludir: 'ser o no ser' como referencia breve y compartida"],["Quote briefly and accurately.","Cita brevemente y con exactitud."],["Quotes add authority and wit.","Las citas dan autoridad e ingenio."]], ex:["As Wilde put it...","Como dijo Wilde..."]}
 ], qs:[
  {q:"Who wrote 'I can resist everything except temptation'?", a:"Oscar Wilde"},
  {q:"Complete: All that glitters is not ____.", a:"gold"},
  {q:"Who wrote 'No man is an island'?", a:"John Donne"}
 ] },

{ cat:"Communication & British Culture", type:"Expressions", lvl:"C2", icon:"🪞", t:"Hedging and Tentative Formal Speech", es:"Atenuación y habla formal tentativa", d:"Cómo suavizar afirmaciones, críticas y peticiones con precisión y cortesía.",
 boxes:[
  {e:"🌫️", h:"Hedging verbs and adverbs", es:"Verbos y adverbios atenuadores", i:[["seem, appear, tend to","parecer, tender a"],["arguably, presumably, conceivably","posiblemente, presumiblemente, concebiblemente"],["to some extent, in a sense","hasta cierto punto, en cierto sentido"]], ex:["This is, arguably, his finest work.","Esta es, posiblemente, su mejor obra."]},
  {e:"🙏", h:"Tentative requests", es:"Peticiones tentativas", i:[["I wonder if you could possibly...","Me pregunto si podría usted..."],["I was wondering whether you might...","Me preguntaba si usted podría..."],["Would you mind awfully if...?","¿Le importaría muchísimo si...?"]], ex:["I wonder if you might lend me a hand.","Me pregunto si podría echarme una mano."]},
  {e:"🧐", h:"Softening disagreement", es:"Suavizar el desacuerdo", i:[["I'm not sure I'd go quite that far.","No estoy seguro de que llegaría tan lejos."],["That may be so, but...","Puede ser, pero..."],["With respect, I'd put it differently.","Con respeto, yo lo diría de otro modo."]], ex:["I'm not entirely convinced, I'm afraid.","No estoy del todo convencido, me temo."]},
  {e:"⚠️", h:"Softening bad news", es:"Suavizar malas noticias", i:[["I'm afraid there's been a slight problem.","Me temo que ha habido un pequeño problema."],["Unfortunately, we are unable to...","Lamentablemente, no podemos..."],["I regret to inform you that...","Lamento informarle que..."]], ex:["I'm afraid I must decline.","Me temo que debo declinar."]},
  {e:"🗣️", h:"Vague language", es:"Lenguaje vago", i:[["sort of, kind of, or so","más o menos"],["and so on, and that sort of thing","etcétera, y cosas así"],["something like twenty","unos veinte, aproximadamente"]], ex:["It's sort of a compromise, really.","Es una especie de compromiso, en realidad."]},
  {e:"⚠️", h:"Over-hedging and balance", es:"Exceso de atenuación", i:[["Too many hedges sound evasive.","Demasiadas atenuaciones suenan evasivas."],["Hedge claims, not facts.","Atenúa hipótesis, no hechos."],["Balance: one hedge per claim.","Equilibrio: una atenuación por afirmación."]], ex:["It would appear to be somewhat unlikely.","Parecería algo improbable."]}
 ], qs:[
  {q:"Complete the tentative request: I was ____ whether you might help me.", a:"wondering"},
  {q:"Which adverb means 'it can be argued that': 'This is ____ his best book'?", a:"arguably"},
  {q:"What does 'I'm not sure I'd go quite that far' express?", a:"Polite disagreement."}
 ] }
]);
